    startedAt: new Date().toISOString(),
    payload: {
      scheduled: true,
      dueWindowMinutes: 5,
      triggeredAt: new Date().toISOString()
    }
  }
}];

const routePaths = {
  "follow-up-scheduled": "/api/automation/agent",
  "reminder-generated": "/api/automation/agent",
  "task-created": "/api/automation/agent",
  "escalation-triggered": "/api/automation/agent"
};
const workflowNames = {
  "follow-up-scheduled": "Follow-Up Scheduling",
  "reminder-generated": "Reminder Generation",
  "task-created": "Task Creation",
  "escalation-triggered": "Escalation Rules"
};
const workflowKey = $json.workflowKey;
if (typeof workflowKey !== 'string' || !routePaths[workflowKey]) {
  const supported = Object.keys(routePaths).join(', ');
  throw new Error(`Unsupported Leadsy workflowKey: ${workflowKey ?? 'missing'}. Supported: ${supported}`);
}
return [{
  json: {
    ...$json,
    workflowName: workflowNames[workflowKey],
    actionPath: routePaths[workflowKey],
    validatedAt: new Date().toISOString()
  }
}];

const providerGroups = [
  {
    "key": "email",
    "label": "Operator Email Notifications",
    "purpose": "Optional operator notifications for reminders and escalations. Outreach messages still require Leadsy approval and storage.",
    "leadsyBoundary": "Leadsy keeps auth, CRM, leads, conversations, assignments, task state, and audit history.",
    "fields": [
      {
        "key": "provider",
        "label": "Email provider",
        "env": "EMAIL_PROVIDER",
        "secret": false,
        "required": false
      },
      {
        "key": "smtpHost",
        "label": "SMTP host",
        "env": "SMTP_HOST",
        "secret": false,
        "required": false
      },
      {
        "key": "smtpUser",
        "label": "SMTP user",
        "env": "SMTP_USER",
        "secret": false,
        "required": false
      },
      {
        "key": "smtpPassword",
        "label": "SMTP password",
        "env": "SMTP_PASSWORD",
        "secret": true,
        "required": false
      },
      {
        "key": "resendApiKey",
        "label": "Resend API key",
        "env": "RESEND_API_KEY",
        "secret": true,
        "required": false
      },
      {
        "key": "postmarkServerToken",
        "label": "Postmark server token",
        "env": "POSTMARK_SERVER_TOKEN",
        "secret": true,
        "required": false
      }
    ]
  }
];
const routeProviderRequirements = {
  "follow-up-scheduled": [],
  "reminder-generated": [],
  "task-created": [],
  "escalation-triggered": []
};
const env = typeof $env === 'object' && $env ? $env : process.env;
function hasValue(name) {
  return Boolean(String(env[name] ?? '').trim());
}
function configured(group) {
  if (group.key === 'email') {
    return hasValue('SMTP_HOST') || hasValue('RESEND_API_KEY') || hasValue('POSTMARK_SERVER_TOKEN');
  }
  const required = group.fields.filter((field) => field.required);
  return required.length ? required.every((field) => hasValue(field.env)) : group.fields.some((field) => hasValue(field.env));
}
const providerConfig = Object.fromEntries(providerGroups.map((group) => [group.key, {
  label: group.label,
  source: 'n8n',
  configured: configured(group),
  purpose: group.purpose,
  leadsyBoundary: group.leadsyBoundary,
  fields: group.fields.map((field) => ({
    key: field.key,
    label: field.label,
    env: field.env,
    secret: field.secret,
    required: field.required,
    configured: hasValue(field.env),
    value: field.secret ? undefined : (String(env[field.env] ?? '').trim() || undefined)
  }))
}]));
const requiredProviderConfig = routeProviderRequirements[$json.workflowKey] ?? [];
const providerConfigMissing = requiredProviderConfig.filter((key) => !providerConfig[key]?.configured);
return [{
  json: {
    ...$json,
    providerConfigSource: 'n8n',
    providerConfig,
    requiredProviderConfig,
    providerConfigMissing
  }
}];

return [{
  json: {
    ...$json,
    contextSource: 'leadsy-api',
    contextRequest: {
      workflowKey: $json.workflowKey,
      tenantId: $json.tenantId,
      ownerId: $json.ownerId,
      leadId: $json.leadId,
      taskId: $json.taskId,
      conversationId: $json.conversationId,
      source: 'n8n-backend-agent'
    }
  }
}];

const commands = Array.isArray($json.providerCommands) ? $json.providerCommands : [];
return [{
  json: {
    ...$json,
    providerCommand: {
      toolKey: "email",
      label: "Operator Email Notification",
      source: 'n8n',
      status: ($json.providerConfigMissing || []).length ? 'blocked_provider_config' : 'ready_for_manual_wiring',
      workflowKey: $json.workflowKey,
      guardrail: 'No durable business state is written outside the Leadsy gateway.'
    },
    providerCommands: [
      ...commands,
      {
        toolKey: "email",
        label: "Operator Email Notification",
        source: 'n8n',
        status: ($json.providerConfigMissing || []).length ? 'blocked_provider_config' : 'ready_for_manual_wiring'
      }
    ]
  }
}];

const writeCommands = Array.isArray($json.leadsyWriteCommands) ? $json.leadsyWriteCommands : [];
return [{
  json: {
    ...$json,
    leadsyWriteCommand: {
      writerKey: "tasks-reminders",
      label: "Task + Reminder Writer",
      source: 'n8n',
      status: 'ready_for_leadsy_gateway',
      workflowKey: $json.workflowKey
    },
    leadsyWriteCommands: [
      ...writeCommands,
      {
        writerKey: "tasks-reminders",
        label: "Task + Reminder Writer",
        source: 'n8n',
        status: 'ready_for_leadsy_gateway'
      }
    ]
  }
}];

const writeCommands = Array.isArray($json.leadsyWriteCommands) ? $json.leadsyWriteCommands : [];
return [{
  json: {
    ...$json,
    leadsyWriteCommand: {
      writerKey: "escalations",
      label: "Escalation Writer",
      source: 'n8n',
      status: 'ready_for_leadsy_gateway',
