    },
    leadsyWriteCommands: [
      ...writeCommands,
      {
        writerKey: "escalations",
        label: "Escalation Writer",
        source: 'n8n',
        status: 'ready_for_leadsy_gateway'
      }
    ]
  }
}];

const writeCommands = Array.isArray($json.leadsyWriteCommands) ? $json.leadsyWriteCommands : [];
return [{
  json: {
    ...$json,
    leadsyWriteCommand: {
      writerKey: "audit-events",
      label: "Audit Event Writer",
      source: 'n8n',
      status: 'ready_for_leadsy_gateway',
      workflowKey: $json.workflowKey
    },
    leadsyWriteCommands: [
      ...writeCommands,
      {
        writerKey: "audit-events",
        label: "Audit Event Writer",
        source: 'n8n',
        status: 'ready_for_leadsy_gateway'
      }
    ]
  }
}];
